"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8566],{63999:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PerkUpgradeGuiController","desc":"Binds the Studio-authored `StarterGui.PerkUpgradeGui` to `PerkClient`. Never\\nbuilds layout: perk cards are clones of the authored `ExampleItem1` (unlocked)\\nand `ExampleItem3` (locked). A TopbarPlus icon (toggle key P) is the single\\nsource of truth for open/closed. `RespecButton` resets the selected perk on a\\nhold (`HoldButton`).\\n\\nThe list shows unlocked perks, locked perks the player is high enough to buy,\\nand locked perks at the next level milestone (the lowest `UnlockLevel` above\\nthe player\'s level) as a preview. Everything further out stays hidden.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/PerkUpgradeGuiController.client.luau"}}')}}]);